from pysat.solvers import Solver
from itertools import combinations

n = 20
# Map each pair (i,j) with i<j to a variable ID
x_id = {}
cur = 1
for i in range(n):
    for j in range(i+1, n):
        x_id[(i,j)] = cur
        cur += 1
num_x = cur - 1

# Map c_{i,j,k} for i<j, k not in {i,j}
c_id = {}
for i in range(n):
    for j in range(i+1, n):
        for k in range(n):
            if k == i or k == j:
                continue
            c_id[(i,j,k)] = cur
            cur += 1
num_c = cur - 1 - num_x

print(f"x variables: {num_x}, c variables: {num_c}, total: {cur-1}")

clauses = []

# 1. Triangle-free constraints: for each triple, not all three edges present
for a,b,c in combinations(range(n), 3):
    # edges are (a,b), (a,c), (b,c)
    # clause: ~x_ab OR ~x_ac OR ~x_bc
    clauses.append([-x_id[(a,b)], -x_id[(a,c)], -x_id[(b,c)]])

# 2. Maximality constraints: for each pair (i,j), either edge present or some common neighbor
# For each pair (i,j):
#   x_{i,j} OR (OR_{k} c_{i,j,k})
# For each c_{i,j,k}:
#   c_{i,j,k} -> x_{i,k}  =>  ~c OR x_{i,k}
#   c_{i,j,k} -> x_{j,k}  =>  ~c OR x_{j,k}
#   (x_{i,k} AND x_{j,k}) -> c_{i,j,k}  =>  ~x_{i,k} OR ~x_{j,k} OR c
for i in range(n):
    for j in range(i+1, n):
        # main clause
        clause = [x_id[(i,j)]]
        for k in range(n):
            if k == i or k == j:
                continue
            cid = c_id[(i,j,k)]
            clause.append(cid)
            # c -> x_{i,k}
            clauses.append([-cid, x_id[tuple(sorted((i,k)))]]])
            # c -> x_{j,k}
            clauses.append([-cid, x_id[tuple(sorted((j,k)))]]])
            # x_{i,k} & x_{j,k} -> c
            clauses.append([-x_id[tuple(sorted((i,k)))], -x_id[tuple(sorted((j,k)))], cid])
        clauses.append(clause)

print(f"Total clauses: {len(clauses)}")

# Fixed assignments
fixed = [
    (1,18), (4,18), (16,18), (4,19), (17,18), (11,19), (3,19)
]

# Add unit clauses
for u,v in fixed:
    clauses.append([x_id[(u,v)]])

# Solve
with Solver(name='g3') as solver:
    for cl in clauses:
        solver.add_clause(cl)
    sat = solver.solve()
    print("SAT:", sat)
    if sat:
        model = solver.get_model()
        # Extract edges
        edges = []
        for (i,j), vid in x_id.items():
            if vid in model:
                edges.append((i,j))
            elif -vid in model:
                pass
            else:
                # variable not in model? should not happen with standard solver
                pass
        print("Number of edges:", len(edges))
        print("Edges:", edges)
        # Verify triangle-free
        # Verify maximal
        # Let's do quick checks
        edge_set = set(edges)
        # triangle check
        tri = False
        for a,b,c in combinations(range(n), 3):
            if (a,b) in edge_set and (a,c) in edge_set and (b,c) in edge_set:
                tri = True
                print("Triangle found:", a,b,c)
                break
        print("Has triangle:", tri)
        # maximal check: for each non-edge, check common neighbor
        non_max = []
        for i in range(n):
            for j in range(i+1, n):
                if (i,j) not in edge_set:
                    found = False
                    for k in range(n):
                        if k==i or k==j:
                            continue
                        if (min(i,k), max(i,k)) in edge_set and (min(j,k), max(j,k)) in edge_set:
                            found = True
                            break
                    if not found:
                        non_max.append((i,j))
        print("Non-maximal non-edges:", non_max)

